export const stockItems=Object.fromEntries(Object.entries(inventories).map(([trade,groups])=>[trade,bank(groups.flatMap(group=>{
  const [family,variants]=group.split(':');return variants.split('|').map(variant=>`${variant} ${family}`);
}),`${trade} substantive inventory`)]));
export const expandedStockSources=Object.fromEntries(Object.entries(stockItems).map(([trade,items])=>[`stock_${trade}`,items.map(item=>item[0].toUpperCase()+item.slice(1)+'.')]));
